def corr(seed, p, n, decoy):
    rng = np.random.default_rng(seed)
    X = rng.normal(size=(n, p)) + 1.5 * rng.normal(size=(n, 1))
    if decoy:
        X[:, -3:] = X[:, :3] + decoy * rng.normal(size=(n, 3))
    y = X @ rng.uniform(-1.4, 1.4, p) + 0.1 * rng.normal(size=n)
    return (X, y)
